<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_login();
$cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart.php');exit;}
$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks)");$s->execute($ids);$products=$s->fetchAll();$total=0;foreach($products as $p)$total+=$p['price']*($cart[$p['id']]??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$address=trim($_POST['address']??'');$payment=$_POST['payment']??'Contraentrega';if($address===''){flash('Ingresa una dirección de entrega.','error');}else{try{$pdo->beginTransaction();$order=$pdo->prepare("INSERT INTO orders(user_id,total,status,shipping_address,payment_method) VALUES(?,?,?,?,?)");$order->execute([current_user()['id'],$total,'Recibido',$address,$payment]);$orderId=(int)$pdo->lastInsertId();$line=$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)");foreach($products as $p){$line->execute([$orderId,$p['id'],$cart[$p['id']]??0,$p['price']]);}$pdo->commit();unset($_SESSION['cart']);header('Location: order_success.php?id='.$orderId);exit;}catch(Throwable $e){$pdo->rollBack();flash('No se pudo crear el pedido. Verifica la base de datos.','error');}}}
$pageTitle='Finalizar compra | UNIK';require __DIR__.'/includes/header.php';
?>
<section class="page-intro compact"><span class="eyebrow">UN PASO MÁS</span><h1>Finaliza tu <span>compra</span></h1><p>Completa los datos para registrar tu pedido.</p></section>
<form method="post" class="checkout-layout"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><section class="form-card"><h2>Información de entrega</h2><label>Dirección de envío<input required name="address" placeholder="Calle, carrera, número, barrio y ciudad"></label><label>Método de pago<select name="payment"><option>Contraentrega</option><option>Nequi (demostración)</option><option>Bancolombia (demostración)</option><option>Tarjeta (demostración)</option><option>Efecty (demostración)</option></select></label><p class="form-hint">Los métodos electrónicos son únicamente demostrativos. No se procesan pagos reales.</p></section><aside class="summary-card"><h2>Resumen</h2><?php foreach($products as $p): ?><div class="summary-row"><span><?= e($p['name']) ?> × <?= (int)$cart[$p['id']] ?></span><strong><?= money($p['price']*$cart[$p['id']]) ?></strong></div><?php endforeach; ?><div class="summary-total"><span>Total</span><strong><?= money($total) ?></strong></div><button class="btn btn-primary btn-full">Crear pedido →</button></aside></form>
